extends Control

@onready var play_button: Button = $Margin/MainLayout/PlayButton


func _ready() -> void:
	play_button.pressed.connect(_on_play_button_pressed)


func _on_play_button_pressed() -> void:
	get_tree().change_scene_to_file("res://basket.tscn")

extends CanvasLayer

@onready var score_label: Label = $MarginContainer/HBoxContainer/ScoreLabel
@onready var lives_container: HBoxContainer = $MarginContainer/HBoxContainer/LivesContainer


func update_score(new_score: int) -> void:
	if score_label != null:
		score_label.text = "Punti: " + str(new_score)


func update_lives(current_lives: int) -> void:
	if lives_container != null:
		var icons: Array[Node] = lives_container.get_children()
		for i in range(icons.size()):
			var icon := icons[i] as CanvasItem
			if icon != null:
				icon.visible = (i < current_lives)

extends Control

@onready var resume_button: Button = %ResumeButton
@onready var restart_button: Button = %RestartButton
@onready var menu_button: Button = %MenuButton


func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	hide()
	resume_button.pressed.connect(_on_resume_button_pressed)
	restart_button.pressed.connect(_on_restart_button_pressed)
	menu_button.pressed.connect(_on_menu_button_pressed)


func _input(event: InputEvent) -> void:
	if event.is_action_pressed("pause") and not event.is_echo():
		get_viewport().set_input_as_handled()
		if get_tree().paused:
			resume_game()
		else:
			pause_game()


func pause_game() -> void:
	get_tree().paused = true
	show()


func resume_game() -> void:
	get_tree().paused = false
	hide()


func _on_resume_button_pressed() -> void:
	resume_game()


func _on_restart_button_pressed() -> void:
	get_tree().paused = false
	get_tree().change_scene_to_file("res://basket.tscn")


func _on_menu_button_pressed() -> void:
	get_tree().paused = false
	get_tree().change_scene_to_file("res://main_menu.tscn")

extends Sprite2D

signal lives_changed(current_lives: int)
signal score_changed(new_score: int)

@export var speed: float = 300.0
@export var max_lives: int = 3

var score: int = 0
var lives: int = 3

@onready var hud: CanvasLayer = $HUD


func _ready() -> void:
	lives = max_lives
	if hud != null:
		lives_changed.connect(hud.update_lives)
		score_changed.connect(hud.update_score)
		hud.update_lives(lives)
		hud.update_score(score)


func _process(delta: float) -> void:
	var direction: float = Input.get_axis("move_left", "move_right")
	position.x += direction * speed * delta
	position.x = clampf(position.x, 64.0, 1088.0)
